import {matchSession} from './match-session.js';import {PITCHSIDE,clipClock} from './pitchside-story.js';import {visionWindow} from './vision-window.js';
const el=(t,c,s)=>{const n=document.createElement(t);if(c)n.className=c;if(s)n.textContent=s;return n;};
export function addVisionCheck(root){
 const card=el('section','vision-check'),head=el('div','vision-heading'),button=el('button','red-button','Check these frames with Azure AI'),status=el('p','vision-status'),frames=el('div','vision-frames'),result=el('div','vision-result');
 head.append(el('div','', ''),button);head.firstChild.append(el('span','eyebrow','INDEPENDENT PIXEL CHECK'),el('h3','','Let the images answer.'));
 card.append(head,el('p','vision-intro','Azure examines up to four frames from this shot, without reading our annotations. Its candidate observation stays separate from verified evidence and match statistics.'),frames,status,result);root.append(card);let activeKey='',sequence=0;
 const text={en:['Check these frames with Azure AI','Reading the selected frames…','AI CANDIDATE · HUMAN REVIEW REQUIRED'],es:['Revisar fotogramas con Azure AI','Leyendo los fotogramas seleccionados…','PROPUESTA DE IA · REQUIERE REVISIÓN'],pt:['Verificar quadros com Azure AI','Lendo os quadros selecionados…','CANDIDATO DA IA · REQUER REVISÃO']};
 function update(s){if(s.source!=='pitchside'||s.section!=='truth')return;const window=visionWindow(s.clipTime),key=window.frames.map(f=>f.id).join(':')+s.language;if(activeKey===key)return;activeKey=key;sequence++;button.disabled=false;button.textContent=text[s.language][0];result.replaceChildren();status.textContent='Evidence through '+clipClock(s.clipTime)+' · one frame per second · no cross-cut inference';frames.replaceChildren();for(const f of window.frames){const item=el('figure'),img=el('img');img.src=f.path;img.alt='Film at '+clipClock(f.second);item.append(img,el('figcaption','',clipClock(f.second)));frames.append(item);}}
 button.onclick=async()=>{const s=matchSession.get(),request=++sequence;button.disabled=true;status.textContent=text[s.language][1];try{const config=await fetch('api-config.json').then(r=>r.json()),base=['localhost','127.0.0.1'].includes(location.hostname)?'':config.baseUrl||'';const r=await fetch(base+'/api/vision-check',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({clip_id:PITCHSIDE.id,time:s.clipTime,language:s.language}),signal:AbortSignal.timeout(40000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Frame check unavailable');if(request!==sequence)return;result.replaceChildren(el('span','eyebrow',text[s.language][2]),el('h4','',data.observation),el('p','',data.limitation));const exportButton=el('button','outline-button','Export candidate + frame references ↓');exportButton.onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download='btr-vision-candidate.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};result.append(exportButton);status.textContent=(data.cached?'CACHED VISION CHECK':'AZURE VISION CHECK')+' · '+data.frame_ids.join(', ')+' · not added to match statistics';}catch(e){if(request===sequence)status.textContent=e.message;}finally{if(request===sequence)button.disabled=false;}};
 matchSession.subscribe(update);update(matchSession.get());
}
